// Route incoming messages based on type
const body = $input.first().json.body || $input.first().json;

let messageType = 'text';
let routeOutput = 3; // default to text handling

// Check if it's an image (media URL present)
if (body.media_url || 
    (body.user_input_data && body.user_input_data[0]?.answer?.match(/^https?:\/\/.+\.(jpg|jpeg|png|gif|webp)/i))) {
  messageType = 'image';
  routeOutput = 0;
}
// Check if it's a flow response with measurements
else if (body.user_input_data && body.flow_id) {
  messageType = 'flow_response';
  routeOutput = 1;
}
// Check if AI chat mode requested
else if (body.message?.toLowerCase().includes('help') || 
         body.message?.toLowerCase().includes('not sure') ||
         body.context?.mode === 'ai_chat') {
  messageType = 'ai_chat';
  routeOutput = 2;
}

return [{
  json: {
    ...body,
    messageType,
    routeOutput,
    phoneNumber: body.chat_id || body.from,
    senderName: body.first_name || body.profile_name || 'Customer',
    imageUrl: body.media_url || body.user_input_data?.[0]?.answer
  }
}];

// Prepare Gemini Vision API request for glass measurement extraction
const prev = $input.first().json;
const base64Image = prev.data;

if (!base64Image) {
  throw new Error('No base64 image found');
}

// Get original webhook data
const webhookData = $('BotSailor Webhook').first().json.body || $('BotSailor Webhook').first().json;

const prompt = `
You are a glass measurement extraction expert for a South African glazing company.

Analyze this image and extract glass/window measurements.

Look for:
1. Dimensions written on paper, tape measure, or measurement tools
2. Standard window/door frame sizes
3. Any written measurements in mm or cm
4. Multiple pieces if shown

IMPORTANT RULES:
- Convert all measurements to millimeters (mm)
- If measurements are in cm, multiply by 10
- Width comes before Height (W x H format)
- Note if the image shows a shower, door, or low-level window (below 800mm from floor)
- These locations REQUIRE safety glass per SANS 10400-N

Output ONLY valid JSON in this exact format:
{
  "measurements": [
    {"width": 1200, "height": 900, "quantity": 1}
  ],
  "glassType": "clear",
  "location": "window",
  "requiresSafetyGlass": false,
  "confidence": "high",
  "notes": "any observations"
}

If you cannot determine measurements clearly, set confidence to "low".
`.trim();

return [{
  json: {
    contents: [{
      role: 'user',
      parts: [
        { text: prompt },
        {
          inline_data: {
            mime_type: 'image/jpeg',
            data: base64Image
          }
        }
      ]
    }],
    phoneNumber: webhookData.chat_id || webhookData.from,
    senderName: webhookData.first_name || 'Customer'
  }
}];

// Parse Gemini Vision response and extract measurement data
const response = $input.first().json;
const webhookData = $('BotSailor Webhook').first().json.body || $('BotSailor Webhook').first().json;
const prepareData = $('Prepare Gemini Request').first().json;

const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '';

let extractedData;
try {
  // Find JSON in the response
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    extractedData = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  extractedData = {
    measurements: [],
    confidence: 'low',
    notes: 'Could not parse measurements from image. Please provide dimensions in format: Width x Height (mm)'
  };
}

// Validate required fields
if (!extractedData.measurements || extractedData.measurements.length === 0) {
  extractedData.confidence = 'low';
  extractedData.notes = 'No measurements detected. Please send clearer image or type dimensions.';
}

return [{
  json: {
    ...extractedData,
    rawResponse: text,
    phoneNumber: prepareData.phoneNumber,
    senderName: prepareData.senderName
  }
}];

// Format the quote response for WhatsApp
const quote = $input.first().json;

let message = '';

if (quote.success) {
  message = `✅ *Quote Ready!*\n\n`;
  message += `Quote #: *${quote.quoteNumber}*\n`;
  message += `─────────────────\n\n`;

  quote.items.forEach((item, i) => {
    message += `${i + 1}. ${item.description}\n`;
    message += `   📐 Size: ${item.width}mm × ${item.height}mm\n`;
    message += `   📦 Qty: ${item.quantity}\n`;
    message += `   💰 R${item.lineTotal.toFixed(2)}\n\n`;
  });

  if (quote.safetyGlassRequired) {
    message += `⚠️ *Safety glass required*\n`;
    message += `${quote.safetyReason}\n\n`;
  }

  message += `─────────────────\n`;
  message += `Subtotal: R${quote.subtotal.toFixed(2)}\n`;
  message += `VAT (15%): R${quote.vat.toFixed(2)}\n`;
  message += `*TOTAL: R${quote.total.toFixed(2)}*\n\n`;
  message += `💳 Deposit Required: R${quote.depositRequired.toFixed(2)}\n\n`;
  message += `⏰ Valid for 7 days\n\n`;
  message += `📄 View full quote: ${quote.pdfUrl}`;

} else {
  message = `❌ Sorry, I couldn't generate a quote.\n\n`;
  message += `${quote.error || 'Please try again or contact us directly.'}\n\n`;
  message += `📞 Call: 011 XXX XXXX`;
}

return [{
  json: {
    message,
    phoneNumber: quote.phoneNumber,
    quoteUrl: quote.pdfUrl,
    quoteNumber: quote.quoteNumber,
    quoteId: quote.quoteId,
    total: quote.total,
    depositRequired: quote.depositRequired,
    success: quote.success
  }
}];

