// Prepare AI Chat request for complex questions
const webhookData = $input.first().json;

const systemPrompt = `You are a helpful glass and glazing expert assistant for a South African glazing company in Gauteng.

You help customers understand:
1. Glass types and their applications
2. Safety requirements (SANS 10400-N)
3. Pricing guidance (without exact quotes)
4. Installation considerations

IMPORTANT RULES:
- Always recommend safety glass for: showers, doors, sidelights, low-level windows (below 800mm), balustrades, overhead glazing
- Mention that toughened or laminated glass is REQUIRED BY LAW for these applications per SANS 10400-N
- If customer provides measurements, tell them you can generate an instant quote
- Never provide exact prices - say "for an accurate quote, I'll need your measurements"
- Be friendly but professional
- Use South African terminology and Rand (R) for any price references
- Keep responses concise for WhatsApp

If the customer seems ready to get a quote, end with:
"Would you like me to generate a quote? Just send me the measurements (width x height in mm) or a photo!"`;

return [{
  json: {
    contents: [{
      role: 'user',
      parts: [{ text: webhookData.message || webhookData.body?.message }]
    }],
    systemInstruction: {
      parts: [{ text: systemPrompt }]
    },
    phoneNumber: webhookData.phoneNumber,
    senderName: webhookData.senderName
  }
}];

// Extract AI response and send via WhatsApp
const response = $input.first().json;
const prepareData = $('Prepare AI Chat').first().json;

const aiResponse = response.candidates?.[0]?.content?.parts?.[0]?.text || 
  'Sorry, I could not process your question. Please try rephrasing or type MENU for options.';

return [{
  json: {
    message: aiResponse,
    phoneNumber: prepareData.phoneNumber
  }
}];
